input.command:
rm -f /tmp/httpstat_body /tmp/httpstat_headers
curl -sS -L --max-time 30 -w '
CURL_EXIT:%{exitcode}
HTTP_CODE:%{http_code}
CONTENT_TYPE:%{content_type}
' -D /tmp/httpstat_headers -o /tmp/httpstat_body 'https://httpstat.us/200'; echo '--- headers ---'; cat /tmp/httpstat_headers 2>/dev/null || true; echo '--- body ---'; cat /tmp/httpstat_body 2>/dev/null || true
